  "outline": [
    {
      "title": "泰勒公式入门与核心思想",
      "summary": "介绍泰勒公式的基本概念：如何用多项式近似函数，以及它在近似计算和误差分析中的重要性。",
      "kc_names": ["泰勒公式"]
    },
    {
      "title": "拉格朗日余项与误差估计",
      "summary": "讲解拉格朗日余项的形式及其如何给出截断误差的上界，是误差分析中最常用的工具。",
      "kc_names": ["拉格朗日余项"]
    },
    {
      "title": "常见函数的泰勒展开式",
      "summary": "列出指数函数、正弦函数、对数函数等在零点附近的展开式，是极限计算和等价无穷小替换的基础。",
      "kc_names": ["泰勒公式"]
    }
  ],
  "glossary": [
    {"term": "泰勒公式", "definition": "将光滑函数在某点附近展开为多项式，用于近似计算和误差分析。"},
    {"term": "拉格朗日余项", "definition": "泰勒展开中截断多项式与原函数之间的误差，用高阶导数在区间内某点的值表示。"},
    {"term": "展开式", "definition": "函数按泰勒公式写成的多项式形式，如 $e^x = 1 + x + x^2/2! + \\cdots$。"},
    {"term": "截断误差", "definition": "用有限项多项式近似函数时，舍去高阶项产生的误差。"},
    {"term": "高阶导数", "definition": "函数多次求导后的导数，用于泰勒展开的系数计算。"},
    {"term": "等价无穷小", "definition": "极限计算中，两个趋于零的量比值趋于1，常用泰勒展开判断。"}
  ],
  "suggested_questions": [
    "泰勒公式如何用于近似计算 $\\sin(0.1)$？",
    "拉格朗日余项中的 $\\xi$ 是什么？如何确定其范围？",
    "写出 $e^x$ 在 $x=0$ 处的三阶泰勒展开式。",
    "如何用泰勒展开求极限 $\\lim_{x\\to 0} \\frac{\\sin x - x}{x^3}$？",
    "拉格朗日余项与佩亚诺余项有何区别？"
  ]
}
